const { fields, header } = require('./columns.cjs');
const { csvCell } = require('./cell.cjs');
function download(rows) {
  return [header,...rows.map(row => fields.map(key => csvCell(row[key])).join(','))].join('\n') + '\n';
}
module.exports = { download };

