const test = require('node:test');
const assert = require('node:assert/strict');
const { download } = require('../catalog/service.cjs');
const { csvCell } = require('../catalog/cell.cjs');
test('CSV cells quote delimiters, line endings and every embedded quote', () => {
  const rows = Object.freeze([
    Object.freeze({sku:'C8',description:'blue, large'}),
    Object.freeze({sku:'Q"9',description:'say "yes" and "no"'}),
    Object.freeze({sku:'L4',description:'top\nbottom'}),
    Object.freeze({sku:'R3',description:'left\rright'}),
    Object.freeze({sku:'N2',description:'a\r\nb'}),
    Object.freeze({sku:'',description:' plain '})
  ]);
  assert.equal(download(rows), 'SKU,Description\nC8,"blue, large"\n"Q""9","say ""yes"" and ""no"""\nL4,"top\nbottom"\nR3,"left\rright"\nN2,"a\r\nb"\n, plain \n');
  assert.equal(download([]),'SKU,Description\n');
  assert.equal(csvCell('""'),'""""""');
  assert.equal(csvCell('a,b"c\nd'),'"a,b""c\nd"');
  assert.equal(csvCell('simple'),'simple');
  assert.equal(csvCell(''),'');
});

